const express = require('express');
const helmet = require('helmet');
const { body, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();

// Security middleware - should be near the top
app.use(helmet({\n  contentSecurityPolicy: {\n    directives: {\n      defaultSrc: ["'self'"],\n      scriptSrc: ["'self'", "'unsafe-inline'"],\n      styleSrc: ["'self'", "'unsafe-inline'"],\n      imgSrc: ["'self'", "data:"],\n    },\n  },\n}));

// Rate limiting to prevent abuse
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({\n  windowMs: 15 * 60 * 1000, // 15 minutes\n  max: 100 // limit each IP to 100 requests per windowMs\n});
app.use(limiter);

// Parse JSON bodies
app.use(express.json({\n  limit: '10kb' // Limit request size\n}));

// Health check - no input validation needed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation
app.get('/users', 
  // Validate query parameters
  [
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer')
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array() 
      });
    }

    // Get validated parameters
    const limit = req.body.limit ? parseInt(req.body.limit) : 10;
    const page = req.body.page ? parseInt(req.body.page) : 1;

    // Mock user data
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const paginatedUsers = mockUsers.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: mockUsers.length,
        pages: Math.ceil(mockUsers.length / limit)
      }
    });
  }
);

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

// Global error handler (should be last)
app.use((err, req, res, next) => {
  console.error('Unexpected error:', err.stack);

  // Don't leak sensitive error details in production
  const isProd = process.env.NODE_ENV === 'production';

  res.status(500).json({
    error: isProd ? 'Internal server error' : err.message
  });
});

// Use environment variable for port, with fallback
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);

  // Log to help with canary detection
  if (process.env.NODE_ENV !== 'production') {
    console.log('Environment:', process.env.NODE_ENV || 'development');
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

