const express = require('express');
const router = express.Router();

// In-memory user store
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Input validation function
function validateUserInput(userId) {
  // Check if userId is provided
  if (!userId) {
    return { valid: false, message: 'User ID is required' };
  }

  // Check if userId is a positive integer
  const id = parseInt(userId, 10);
  if (isNaN(id) || id <= 0 || !Number.isInteger(id)) {
    return { valid: false, message: 'User ID must be a positive integer' };
  }

  return { valid: true, id };
}

// GET /users - Return all users
router.get('/', (req, res) => {
  try {
    res.json(users);
  } catch (error) {
    console.error('Error retrieving users:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve users'
    });
  }
});

// GET /users/:id - Return specific user by ID
router.get('/:id', (req, res) => {
  try {
    const { id: userId } = req.params;

    // Validate input
    const validation = validateUserInput(userId);
    if (!validation.valid) {
      return res.status(400).json({
        error: 'Invalid input',
        message: validation.message
      });
    }

    // Find user
    const user = users.find(u => u.id === validation.id);
    if (!user) {
      return res.status(404).json({
        error: 'Not found',
        message: `User with ID ${validation.id} not found`
      });
    }

    res.json(user);
  } catch (error) {
    console.error(`Error retrieving user ${req.params.id}:`, error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve user'
    });
  }
});

module.exports = router;

