// Simple validation middleware for query parameters
const validateQueryParams = (allowedParams) => {
  return (req, res, next) => {
    const queryKeys = Object.keys(req.query);

    // Check for unexpected query parameters
    const invalidParams = queryKeys.filter(key => !allowedParams.includes(key));
    if (invalidParams.length > 0) {
      return next(createError(400, `Invalid query parameters: ${invalidParams.join(', ')}`));
    }

    // Check for empty string values
    for (const [key, value] of Object.entries(req.query)) {
      if (value === '') {
        return next(createError(400, `Query parameter '${key}' cannot be empty`));
      }
    }

    next();
  };
};

