const express = require('express');
const createError = require('http-errors');
const logger = require('./lib/logger');
const validation = require('./middleware/validation');

const app = express();

// Security: Set security headers
app.use((req, res, next) => {
  // Prevent XSS and clickjacking
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  // Enable CORS (restricted)
  res.setHeader('Access-Control-Allow-Origin', 'https://trusted.example.com');
  next();
});

// Enhanced health route with input validation
app.get('/health', 
  validation.validateQueryParams(['verbose']), // Allow optional verbose parameter
  (req, res, next) => {
    try {
      // Log request
      logger.info('Health check requested', { path: req.path });

      const response = { 
        status: 'ok', 
        timestamp: new Date().toISOString() 
      };

      // Optional verbose response
      if (req.query.verbose) {
        response.hostname = req.hostname;
        response.protocol = req.protocol;
      }

      res.json(response);
    } catch (error) {
      logger.error('Health check failed', { error: error.message });
      next(createError(500, 'Internal server error'));
    }
  }
);

// Users route with input validation and sanitization
app.get('/users', 
  validation.validateQueryParams(['limit', 'offset', 'fields']),
  (req, res, next) => {
    try {
      logger.info('Users requested', { 
        path: req.path, 
        query: req.query 
      });

      // Validate and sanitize query parameters
      let limit = 10;
      let offset = 0;

      if (req.query.limit) {
        const parsedLimit = parseInt(req.query.limit, 10);
        if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
          return next(createError(400, 'Limit must be a number between 1 and 100'));
        }
        limit = parsedLimit;
      }

      if (req.query.offset) {
        const parsedOffset = parseInt(req.offset, 10);
        if (isNaN(parsedOffset) || parsedOffset < 0) {
          return next(createError(400, 'Offset must be a non-negative number'));
        }
        offset = parsedOffset;
      }

      // Simulated user data
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' }
      ];

      // Apply pagination
      const paginatedUsers = users.slice(offset, offset + limit);

      // Field selection (basic)
      let responseUsers = paginatedUsers;
      if (req.query.fields) {
        const fields = req.query.fields.split(',').map(f => f.trim());
        responseUsers = paginatedUsers.map(user => {
          const filteredUser = {};
          fields.forEach(field => {
            if (user[field] !== undefined) {
              filteredUser[field] = user[field];
            }
          });
          return filteredUser;
        });
      }

      // Add pagination metadata
      res.json({
        data: responseUsers,
        pagination: {
          limit,
          offset,
          total: users.length,
          next: offset + limit < users.length ? `/users?limit=${limit}&offset=${offset + limit}` : null
        }
      });

    } catch (error) {
      logger.error('Users request failed', { 
        error: error.message, 
        path: req.path 
      });
      next(createError(500, 'Internal server error'));
    }
  }
);

// Security: Handle route not found
app.use((req, res, next) => {
  logger.warn('Route not found', { path: req.path });
  next(createError(404, 'Route not found'));
});

// Centralized error handling
app.use((error, req, res, next) => {
  const status = error.status || 500;

  // Log error with details
  logger.error('Request error', {
    error: error.message,
    status,
    path: req.path,
    method: req.method
  });

  // Don't expose internal details in production
  const errorResponse = {
    error: status === 500 ? 'Internal server error' : error.message,
    status
  };

  // Include stack only in development
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = error.stack;
  }

  res.status(status).json(errorResponse);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;

