const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');

const app = express();

// Security middleware
app.use(helmet()); // Set security headers
app.use(mongoSanitize()); // Prevent MongoDB operator injection
app.use(xss()); // Prevent XSS attacks
app.use(hpp()); // Prevent HTTP Parameter Pollution

// Limit request size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  max: 100, // max requests
  windowMs: 15 * 60 * 1000, // 15 minutes
  message: 'Too many requests from this IP, please try again later.',
});

app.use('/api', limiter);

// Input validation function
const validateIdParam = (req, res, next) => {
  const id = req.params.id;
  if (!id) {
    return res.status(400).json({
      error: 'Missing required parameter: id'
    });
  }

  // Validate ID is a positive integer
  const idNum = parseInt(id, 10);
  if (isNaN(idNum) || idNum <= 0 || !Number.isInteger(idNum)) {
    return res.status(400).json({
      error: 'Invalid id parameter: must be a positive integer'
    });
  }

  // Prevent prototype pollution
  if (id === '__proto__' || id === 'constructor' || id === 'prototype') {
    return res.status(400).json({
      error: 'Invalid parameter value'
    });
  }

  req.params.id = idNum; // Use validated integer
  next();
};

// Enhanced health check with proper error handling
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if present
    if (req.query && Object.keys(req.query).length > 5) {
      return res.status(400).json({
        error: 'Too many query parameters'
      });
    }

    // Sanitize any query inputs
    const showDetails = req.query.details === 'true';

    const healthResponse = {
      status: 'ok', 
      timestamp: new Date().toISOString()
    };

    if (showDetails) {
      healthResponse.environment = process.env.NODE_ENV || 'development';
    }

    res.json(healthResponse);
  } catch (error) {
    // Generic error message to avoid information leakage
    console.error('Health check error:', error.message);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    let page = 1;
    let limit = 10;
    let sort = 'name';

    if (req.query.page) {
      const pageNum = parseInt(req.query.page, 10);
      if (isNaN(pageNum) || pageNum < 1) {
        return res.status(400).json({
          error: 'Invalid page parameter'
        });
      }
      page = pageNum;
    }

    if (req.query.limit) {
      const limitNum = parseInt(req.query.limit, 10);
      if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
        return res.status(400).json({
          error: 'Limit must be between 1 and 100'
        });
      }
      limit = limitNum;
    }

    if (req.query.sort) {
      // Whitelist allowed sort fields
      const allowedSorts = ['name', 'id', 'email'];
      if (!allowedSorts.includes(req.query.sort)) {
        return res.status(400).json({
          error: 'Invalid sort parameter'
        });
      }
      sort = req.query.sort;
    }

    // Simulated user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple sorting
    const sortedUsers = [...users].sort((a, b) => {
      if (a[sort] < b[sort]) return -1;
      if (a[sort] > b[sort]) return 1;
      return 0;
    });

    // Pagination
    const startIndex = (page - 1) * limit;
    const paginatedUsers = sortedUsers.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        current: page,
        total: Math.ceil(users.length / limit),
        totalRecords: users.length
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error.message);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Hide detailed error messages in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(error.status || 500).json({
    error: isProduction ? 'Internal server error' : error.message
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

