const express = require('express');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Security headers

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || '*',
  credentials: true,
}));

// Parse JSON bodies
app.use(express.json({
  limit: '10kb' // Limit request size
}));

// Parse URL-encoded bodies
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    // Validate input if any query parameters exist
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: process.env.npm_package_version || '1.0.0'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An error occurred while processing your request' 
    });
  }
});

// Users endpoint with parameter validation
app.get('/users', [
  // Validate query parameters
  (req, res, next) => {
    // Example validation - only allow specific fields to be returned
    const allowedFields = ['id', 'name', 'email'];

    if (req.query.fields) {
      const requestedFields = req.query.fields.split(',');
      const invalidFields = requestedFields.filter(field => !allowedFields.includes(field.trim()));

      if (invalidFields.length > 0) {
        return res.status(400).json({
          error: 'Invalid fields parameter',
          message: `The following fields are not allowed: ${invalidFields.join(', ')}`
        });
      }
    }

    next();
  }
], (req, res) => {
  try {
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter fields if requested
    if (req.query.fields) {
      const fields = req.query.fields.split(',').map(f => f.trim());
      users = users.map(user => {
        const filteredUser = {};
        fields.forEach(field => {
          if (user[field] !== undefined) {
            filteredUser[field] = user[field];
          }
        });
        return filteredUser;
      });
    }

    res.json({
      data: users,
      count: users.length
    });

  } catch (error) {
    console.error('Error in users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An error occurred while retrieving users' 
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    message: `The requested endpoint ${req.method} ${req.path} does not exist.`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Handle specific error types
  if (error.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation error',
      message: error.message
    });
  }

  // Default to 500 for unhandled errors
  res.status(500).json({ 
    error: 'Internal server error',
    message: 'An unexpected error occurred' 
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = server;

