const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const slowDown = require('express-slow-down');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Security headers

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Add delay to slow down brute force attacks
const speedLimiter = slowDown({
  windowMs: 1 * 60 * 1000, // 1 minute
  delayAfter: 10, // allow 10 requests per 15 minutes, then...
  delayMs: 500, // begin adding 500ms of delay per request above 10:
});

app.use(speedLimiter);

// Enable CORS with specific origin
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'https://example.com',
  optionsSuccessStatus: 200,
}));

// Parse JSON bodies
app.use(express.json({
  limit: '10kb', // Limit request body size
}));

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Example validation - you can extend this based on your needs
  const allowedParams = ['page', 'limit', 'sort'];
  const invalidParams = Object.keys(req.query).filter(param => !allowedParams.includes(param));

  if (invalidParams.length > 0) {
    return res.status(400).json({
      error: `Invalid query parameters: ${invalidParams.join(', ')}`,
      allowed: allowedParams
    });
  }

  // Validate parameter values if present
  if (req.query.page && (!Number.isInteger(Number(req.query.page)) || Number(req.query.page) < 1)) {
    return res.status(400).json({ error: 'Page must be a positive integer' });
  }

  if (req.query.limit && (!Number.isInteger(Number(req.query.limit)) || Number(req.query.limit) < 1 || Number(req.query.limit) > 100)) {
    return res.status(400).json({ error: 'Limit must be an integer between 1 and 100' });
  }

  next();
};

// Health check endpoint
app.get('/health', validateQueryParams, (req, res) => {
  try {
    const healthData = {
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Health check failed',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with input validation
app.get('/users', validateQueryParams, (req, res) => {
  try {
    // Simulated users data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination implementation
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    const results = {};

    if (endIndex < users.length) {
      results.next = {
        page: page + 1,
        limit: limit
      };
    }

    if (startIndex > 0) {
      results.previous = {
        page: page - 1,
        limit: limit
      };
    }

    results.data = users.slice(startIndex, endIndex);
    results.total = users.length;
    results.page = page;
    results.pages = Math.ceil(users.length / limit);

    res.json(results);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Failed to retrieve users',
      timestamp: new Date().toISOString()
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.originalUrl} not found`,
    supported_routes: ['/health', '/users']
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak sensitive error information in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(error.status || 500).json({
    error: isProduction ? 'Internal server error' : error.message,
    timestamp: new Date().toISOString()
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.log('Unhandled Rejection:', err.message || err);
  // Close server & exit process
  server.close(() => process.exit(1));
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.log('Uncaught Exception:', err.message || err);
  // Close server & exit process
  server.close(() => process.exit(1));
});

module.exports = app;

